  "qualityChecks": {
    "sources": {
      "pass": true,
      "basis": "唯一原始资料是会话事件 9 的开工原文（A1–A4、E1–E6），已登记于 CONVERSATION-INPUT.md 第 10、18、26、34 行，与 prepare 注入的 instruction 文本逐句一致。任务明令只用条内合成材料、不查网络，故无外部来源需核实；仍待证的是材料所述“G17 已签生效、G18 未生效”等现实状态，本任务按合成前提接受，不作外部证实。"
    },
    "conclusion": {
      "pass": true,
      "basis": "六个判断与材料逐项吻合：E1 ALLOW（所有者读原件）、E5 ALLOW（A2 增补四条件全满足）、E4 DENY（华北不能导出原件，属明确超范围）、E2/E3/E6 HOLD（分别缺华北落点、项目归属、生成时间，适用“四项缺一先挂起”），并正确排除了解密/哈希成功、公开标签、未生效 G18 作为授权依据。表头、编号、每编号一行、值一格只写三值之一、依据列写材料编号，均符合交付要求，无需修订。"
    },
    "method": {
      "pass": true,
      "basis": "先读 PROJECT-GOAL.md 与 CONVERSATION-INPUT.md 全文取得真实原文，再逐行比对 DELIVERY.md；对每条判断回溯到具体规则句，检查四项条件是否逐项覆盖、HOLD 与 DENY 的分界（缺项挂起 vs 明确超范围禁止）、以及“四条件同时满足才 ALLOW”的量词口径。局限：TASK-LEDGER.md 不在读白名单，未核；未做网络查证，符合任务禁令。"
    },
    "alternatives": {
      "pass": true,
      "basis": "E1 可改为仅引 A1 并省去括注，但现括注同样有据；E4 也可写成“A1 禁止导出＋A3 未生效”。此外存在一种更保守的写法：在 E2 依据中显式注明“14 天前满足 30 天条件（A4）”，可省去读者自行推导，属可选改进而非必要修正。"
    },
    "detail": {
      "pass": true,
      "basis": "摘要：交付稿是一张六行结论表，全部正确。依据：E1 对应 A1“仅项目所有者可读取原件”且范围含华北，无条件缺口，ALLOW 无疑；E2 题干未提华北落点，四项缺一即挂起，14 天前经 A4 判定满足 30 天，HOLD 正确；E3 缺项目归属证明，A4 已明示解密成功只证明可读，HOLD 正确；E4 从华北导出原件为 A1 明文禁止，属“明确超范围则禁止”，DENY 而非 HOLD，候选区分正确；E5 恰为 A2 增补的完整条件组合，ALLOW 正确；E6 只有访问时间、无生成时间，A4“未写明的信息一律未知”，HOLD 正确。末行大白话四项概括与表格结论一致，且置于文末。"
    },
    "plain": {
      "pass": true,
      "basis": "这份表六道题都判对了：能放行的两条有完整依据，三条卡在“缺一项先挂起”上，一条因为是从华北往外导原件被明文禁止，所以直接禁。"
    }
  },
